/-- For [the displayed parameters](hyp:d,Q), [Consistency](goal) is the object specified by this definition. -/
def Consistency {d : ℕ} (Q : PotentialLaw d) : Prop :=
  ∀ z, z.2.2.1 ≠ (if z.2.1 then z.2.2.2.2 else z.2.2.2.1) → Q.pmf z = 0

